__NUXT_JSONP__("/it/how-to-apply/student-visa-f1/transfer-students", (function(a){return {data:[{details:{slug:"it",pageTitle:"Studente che chiede il trasferimento | Mentor Language Institute",pageDescription:a,title:"Studente che chiede il trasferimento",image:"\u002Fimages\u002Fhow-to-apply\u002Ftransfer-students\u002Ftransfer-students.jpg",section:[{subtitle:a,description:["-studente che è già iscritto ad un corso di studio negli Stati Uniti \u003Cbr \u002F\u003E-studente che sta frequentando un istituto professionale o altri istituti scolastici \u003Cbr \u002F\u003E-studente con un visto F1 e un I-20"]}],category:[{title:"Procedimento di iscrizione",image:"\u002Fimages\u002Fhow-to-apply\u002Ftransfer-students\u002Fapplication-steps-en.jpg",subtitle:["uno o due mesi prima della data del trasferimento:"],listType:"decimal",lists:["Presentare domanda di iscrizione ad MLI","Inviare i documenti","Prendere parte alla sessione di orientamento","Ricevere il nuovo I-20"],description:["Gli studenti devono avviare la procedura di trasferimento tramite la presentazione della domanda di iscrizione uno o due mesi prima della data di trasferimento desiderata.  è consiglato recarsi alla reception per parlare con lo staff amministrativo dopo aver presentato domanda per confermare che il procedimento di trasferimento è stato avviato dal momento che questo può rivelarsi complicato sulla base del vostro status."]},{title:"Regole per l'annullamento dell'iscrizione",description:["la tassa iniziale di registrazione di $ 150 deve essere pagata al momento dell'iscrizione. Essa non è rimborsabile indipendentemente dal fatto che la domanda venga respinta o l'iscrizione annullata. L'unica eccezione è rappresentata dall'indisponibilità di alloggi."]},{title:"Procedura successiva alla presentazione della domanda",image:"\u002Fimages\u002Fhow-to-apply\u002Ftransfer-students\u002Fapplication-form-en.jpg",description:["Successivamente all'iscrizione, il sistema iMLI elabora la domanda.Gli studenti possono seguire questo processo tramite iMLI."]}],applyOnline:{title:"Iscrizione online",description:["Inserisci le informazioni sul tuo status del Visto\u003Cbr \u002F\u003EContattaci tramite iMLI per qualsiasi informazione","Iscriversi sotto"],btn_label:"Modulo di iscrizione online",admission:{link:"\u002Fit\u002Fadmission",content:["*si prega di tenere la propria carta di credito a portata di mano."]}},dir:"\u002Ftransfer-students",path:"\u002Ftransfer-students\u002Fit",extension:".json",createdAt:"2026-10-22T16:31:31.272Z",updatedAt:"2025-05-26T12:06:27.946Z"}}],fetch:{},mutations:void 0}}("Studente che si trova negli Stati Uniti e vuole richiedere il trasferimento dalla scuola in cui è attualmente iscritto a MLI")));